import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, unzipInputArray } from './test-utils'

describe('TemplateValue with Datapills Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('TemplateValue -> Fluent to XML', () => {
        test('TemplateValue with flow variable datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'template-value-datapills-example.now.ts',
                'template-value'
            )

            // Verify action instance was created
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find the create record action with template value from flow variables
            const createActionWithVars = actionInstances.find(
                (action: any) => action.comment === 'Create record with TemplateValue using flow variable datapills'
            )
            expect(createActionWithVars).toBeDefined()

            // Parse the action inputs
            const inputsArr = unzipInputArray(createActionWithVars.values)
            const getInput = (name: string) => findInput(inputsArr, name)?.value

            // Verify table_name
            expect(getInput('table_name')).toBe('sc_cat_item')

            // Verify values contains TemplateValue with datapills
            const valuesInput = getInput('values')
            expect(valuesInput).toBeDefined()

            // TemplateValue with datapills should be encoded with datapill markers
            expect(valuesInput).toContain('cost=')
            expect(valuesInput).toContain('{{flow_variable.itemCost}}')
            expect(valuesInput).toContain('description=')
            expect(valuesInput).toContain('{{flow_variable.itemDescription}}')
            expect(valuesInput).toContain('category=')
            expect(valuesInput).toContain('{{flow_variable.itemCategory}}')
            expect(valuesInput).toContain('active=')
            expect(valuesInput).toContain('{{flow_variable.isActive}}')
        })

        test('TemplateValue with trigger datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'template-value-datapills-example.now.ts',
                'template-value'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find the create record action with template value from trigger
            const createActionWithTrigger = actionInstances.find(
                (action: any) => action.comment === 'Create record with TemplateValue using trigger datapills'
            )
            expect(createActionWithTrigger).toBeDefined()

            const inputsArr = unzipInputArray(createActionWithTrigger.values)
            const valuesInput = findInput(inputsArr, 'values')?.value

            expect(valuesInput).toBeDefined()
            // Trigger datapills should be converted to {{trigger_name.current.*}} format
            expect(valuesInput).toContain('description=')
            expect(valuesInput).toContain('.current.short_description}}')
            expect(valuesInput).toContain('cost=')
            expect(valuesInput).toContain('.current.priority}}')
            expect(valuesInput).toContain('active=true')
        })

        test('TemplateValue with action output datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'template-value-datapills-example.now.ts',
                'template-value'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find the create record action with template value from action output
            const createActionWithOutput = actionInstances.find(
                (action: any) => action.comment === 'Create record with TemplateValue using action output datapills'
            )
            expect(createActionWithOutput).toBeDefined()

            const inputsArr = unzipInputArray(createActionWithOutput.values)
            const valuesInput = findInput(inputsArr, 'values')?.value

            expect(valuesInput).toBeDefined()
            // Action output datapills should be converted to {{action_label.*}} format
            expect(valuesInput).toContain('description=')
            expect(valuesInput).toContain('.record.short_description}}')
            expect(valuesInput).toContain('cost=200')
        })

        test('TemplateValue with mixed literals and datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'template-value-datapills-example.now.ts',
                'template-value'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThanOrEqual(4)

            // TemplateValue should support mix of literals and datapills
            // Verify at least one action has both types
            const hasLiterals = actionInstances.some((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                const valuesInput = findInput(inputsArr, 'values')?.value
                return valuesInput?.includes('200')
            })

            const hasDatapills = actionInstances.some((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                const valuesInput = findInput(inputsArr, 'values')?.value
                return valuesInput?.includes('{{')
            })

            expect(hasLiterals).toBe(true)
            expect(hasDatapills).toBe(true)
        })

        test('TemplateValue structure and encoding format', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'template-value-datapills-example.now.ts',
                'template-value'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']
            const firstAction = actionInstances[1] // Get second action (first with template)

            const inputsArr = unzipInputArray(firstAction.values)
            const valuesInput = findInput(inputsArr, 'values')?.value

            // TemplateValue should be encoded as ServiceNow query format
            // Format: field1=value1^field2=value2^EQ
            expect(valuesInput).toBeDefined()
            expect(valuesInput).toMatch(/\w+=.*/)

            // Should contain field separators
            if (valuesInput.includes('^')) {
                // If using encoded query format, should end with ^EQ
                expect(valuesInput).toMatch(/\^EQ$/)
            }
        })
    })

    describe('TemplateValue with Datapills - Edge Cases', () => {
        test('TemplateValue with empty fields', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'template-value-datapills-example.now.ts',
                'template-value'
            )

            // Verify all actions were created successfully even with various data types
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']

            // Should have at least 4 actions (3 creates + 1 log)
            expect(actionInstances.length).toBeGreaterThanOrEqual(4)
        })

        test('TemplateValue datapill types preserved', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'template-value-datapills-example.now.ts',
                'template-value'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']
            const createActionWithVars = actionInstances.find(
                (action: any) => action.comment === 'Create record with TemplateValue using flow variable datapills'
            )

            const inputsArr = unzipInputArray(createActionWithVars.values)
            const valuesInput = findInput(inputsArr, 'values')?.value

            // Different data types should be handled correctly
            // Integer datapill
            expect(valuesInput).toContain('cost=')
            expect(valuesInput).toMatch(/cost={{[^}]+}}/)

            // String datapill
            expect(valuesInput).toContain('description=')
            expect(valuesInput).toMatch(/description={{[^}]+}}/)

            // Boolean datapill
            expect(valuesInput).toContain('active=')
            expect(valuesInput).toMatch(/active={{[^}]+}}/)
        })
    })
})
